g:evaluate.expression:
var rosterSpanProposal = ${ref}.sysapproval;
var jvar_contextual_cal_url = new OCRosterSpanApprovalUtil().getContextualCalUrlPerSpanProposal(rosterSpanProposal);
jvar_contextual_cal_url;

var rosterSpanProposal = ${ref}.sysapproval;
var msgArr = [];
var approvalUtil = new OCRosterSpanApprovalUtil();
msgArr.push(approvalUtil.getUserNamePerSpanProposal(rosterSpanProposal));
msgArr.push(approvalUtil.getFromDateDisplayValuePerSpanProposal(rosterSpanProposal));
msgArr.push(approvalUtil.getToDateDisplayValuePerSpanProposal(rosterSpanProposal));
var jvar_header_msg = gs.getMessage('Reviewing time off request for {0}, from {1} to {2}.', msgArr);
jvar_header_msg;

var rosterSpanProposal = ${ref}.sysapproval;
var jvar_proposed_cover_msg = '';
if(rosterSpanProposal.proposed_cover)
	jvar_proposed_cover_msg = gs.getMessage('Proposed covering member by requester is {0}', rosterSpanProposal.proposed_cover.getRefRecord().getDisplayValue());
jvar_proposed_cover_msg;

var rosterSpanProposal = ${ref}.sysapproval;
var jvar_proposal_sys_id = rosterSpanProposal.sys_id + '';
jvar_proposal_sys_id;

var rosterSpanProposal = ${ref}.sysapproval;										
var jvar_proposal_state = rosterSpanProposal.state + '';
jvar_proposal_state;

var rosterSpanProposal = ${ref}.sysapproval;
var jvar_is_coverage_provided = false;
if(rosterSpanProposal.proposed_cover ${AND} jvar_proposal_state != '5')
	jvar_is_coverage_provided = true;
jvar_is_coverage_provided;

var rosterSpanProposal = ${ref}.sysapproval;										
var jvar_proposal_notes = rosterSpanProposal.description + '';
jvar_proposal_notes;

j:jelly.script:
function handleCoverageAction(proposalRecordSysId, isSwapAllowed) {
    var ga = new GlideAjax("AllowCoverageProposalSwap");
    ga.addParam('sysparm_name', "allowAutomaticSwapOfCoverage");
    ga.addParam('sysparm_sys_id', proposalRecordSysId);
    ga.addParam('sysparm_is_swap_allowed', isSwapAllowed);

    ga.getXML(function(response) {
        var resultStatus = response.responseXML.getElementsByTagName("result")
        if (resultStatus[0].getAttribute("status") == "error")
            return;
        showHideCoverageAction(isSwapAllowed);
    });
}
function showHideCoverageAction (showAcceptProposalAction) {
	var elProposedCoverage = document.getElementById("accept_coverage");
	var elRejectCoverage = document.getElementById("reject_coverage");
	var elProposedCoverageMsg = document.getElementById("accept_coverage_msg");
	var elRejectCoverageMsg = document.getElementById("reject_coverage_msg");
	if (showAcceptProposalAction) {
		elRejectCoverage.classList.remove("hide_coverage_action");
		elRejectCoverageMsg.classList.remove("hide_coverage_action");
		elProposedCoverage.classList.add("hide_coverage_action");
		elProposedCoverageMsg.classList.add("hide_coverage_action");
	} else {
		elProposedCoverage.classList.remove("hide_coverage_action");
		elProposedCoverageMsg.classList.remove("hide_coverage_action");
		elRejectCoverage.classList.add("hide_coverage_action");
		elRejectCoverageMsg.classList.add("hide_coverage_action");
	}
}
